import express from 'express';import dotenv from 'dotenv';dotenv.config();const app=express();app.use(express.json());const PORT=Number(process.env.IBM_QUANTUM_GATEWAY_PORT||7193);app.get('/health',(_q,r)=>r.json({ok:true,service:'ibm-quantum-gateway',tokenPresent:!!process.env.IBM_QUANTUM_TOKEN}));app.post('/job',(q,r)=>{if(!process.env.IBM_QUANTUM_TOKEN)return r.status(409).json({ok:false,error:'IBM_QUANTUM_TOKEN missing'});r.json({ok:true,mode:'stub',note:'wire qiskit runtime here',request:q.body})});app.listen(PORT,'0.0.0.0',()=>console.log('ibm quantum gateway',PORT));